package com.nigson.experience.distributor;

import java.util.*;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.atomic.AtomicBoolean;import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Local/test-only stateful API-117 peer; command UUIDs are durable mock idempotency keys. */
public final class StatefulDistributorEntitlementMock implements DistributorService.EntitlementPort {
 private record Stored(DistributorService.EntitlementCommand command,DistributorService.EntitlementAck ack){}
 private final Map<UUID,Stored> accepted=new ConcurrentHashMap<>();private final Map<UUID,DistributorService.EntitlementAck> applications=new ConcurrentHashMap<>();private final AtomicBoolean loseNextResponseAfterAcceptance=new AtomicBoolean(),returnOutOfOrderAcknowledgment=new AtomicBoolean();
 public void timeoutAfterNextAcceptance(){loseNextResponseAfterAcceptance.set(true);}
 public void returnOutOfOrderAcknowledgmentNext(){returnOutOfOrderAcknowledgment.set(true);}
 @Override public synchronized DistributorService.EntitlementAck execute(DistributorService.EntitlementCommand command)throws Exception{if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("COMMERCE_HTTP_INSIDE_EXPERIENCE_TRANSACTION");var prior=accepted.get(command.commandId());if(prior!=null&&!sameCommand(prior.command(),command))throw new IllegalStateException("COMMAND_ID_REUSED");DistributorService.EntitlementAck result;if(prior!=null)result=prior.ack();else{boolean activation=command.decision().equals("ACTIVATE");var current=applications.get(command.applicationId());if(activation&&current!=null||!activation&&(current==null||!current.state().equals("ACTIVE")||current.revision()!=command.expectedVersion()))throw new IllegalStateException("MOCK_INVALID_TRANSITION");UUID organization=current==null?UUID.nameUUIDFromBytes(("local-commerce-org:"+command.applicationId()).getBytes(java.nio.charset.StandardCharsets.UTF_8)):current.organizationId();result=new DistributorService.EntitlementAck(command.commandId(),organization,activation?"ACTIVE":"SUSPENDED",activation?0:current.revision()+1);applications.put(command.applicationId(),result);accepted.put(command.commandId(),new Stored(command,result));}if(loseNextResponseAfterAcceptance.compareAndSet(true,false))throw new java.net.http.HttpTimeoutException("LOCAL_MOCK_TIMEOUT_AFTER_ACCEPTANCE");if(returnOutOfOrderAcknowledgment.compareAndSet(true,false))return new DistributorService.EntitlementAck(UUID.nameUUIDFromBytes("out-of-order-command".getBytes(java.nio.charset.StandardCharsets.UTF_8)),result.organizationId(),result.state(),result.revision());return result;}
 private static boolean sameCommand(DistributorService.EntitlementCommand a,DistributorService.EntitlementCommand b){return a.commandId().equals(b.commandId())&&a.applicationId().equals(b.applicationId())&&a.partyId().equals(b.partyId())&&a.organizationName().equals(b.organizationName())&&a.countryCode().equals(b.countryCode())&&Objects.equals(a.businessReference(),b.businessReference())&&a.decision().equals(b.decision())&&Objects.equals(a.marketId(),b.marketId())&&Objects.equals(a.priceBookId(),b.priceBookId())&&a.expectedVersion()==b.expectedVersion()&&a.idempotencyKey().equals(b.idempotencyKey());}
 public int acceptedCommandCount(){return accepted.size();}
}
